include <robotics.scad>
// LD06 base housing. Origin: mounting face centre (z=0). Connector face +Y, sensor forward −X.
W    = 38.59;           // footprint at mounting face (datasheet)
H    = 20.70;           // base height = 33.50 - 12.80 (datasheet)
drft = 2.0;             // 92° wall draft -> 2° inward per side (datasheet)
Wt   = W - 2*H*tan(drft);   // top width ≈ 37.14
rc   = 5.5;             // corner radius at bottom, scaled from drawing (NOT dimensioned)
rct  = rc - H*tan(drft);
// connector pocket (size scaled from drawing, not dimensioned)
cw = 9.35; ch = 4.2; cz = 3.8; cd = 4.0; clr = 0.2;

$fn = 48;
difference() {
  prismoid(size1=[W,W], size2=[Wt,Wt], h=H, rounding1=rc, rounding2=rct, anchor=BOT);
  // 2x through holes Ø2.45 with Ø4.80 counterbore 11.8 deep from bottom
  for (p = [[-14.1, 14.1], [14.1, -14.1]]) translate([p.x, p.y, 0]) {
    down(0.01) cyl(d=4.80, h=11.8+0.01, anchor=BOT);
    down(0.01) cyl(d=2.45, h=H+0.1, anchor=BOT);
  }
  // blind locating hole Ø2.50 x 5.8 deep from bottom
  translate([15.7, 15.7, -0.01]) cyl(d=2.50, h=5.8+0.01, anchor=BOT);
  // connector pocket on +Y face
  translate([0, W/2 + 1, cz]) cuboid([cw+2*clr, cd + 2 + 1, ch+2*clr], anchor=BACK+CENTER, spin=0, orient=UP)
    ;
}

include <robotics.scad>
// LD06 rotating cap. Origin: cap base centre on base top face. Forward = −X.
D0  = 35.29;              // base diameter (datasheet)
Hc  = 12.80;              // height (datasheet)
D1  = D0 - 2*Hc*tan(1.5); // 91.5° draft -> top Ø ≈ 34.62
rt  = 0.8;                // top edge round (NOT dimensioned)
zl  = Hc - 7.80;          // lens centre, 7.80 below top (datasheet)
dl  = 8.1;                // lens Ø scaled from drawing (NOT dimensioned)
tl  = 1.2;                // lens recess depth (NOT dimensioned)
$fn = 96;
difference() {
  cyl(d1=D0, d2=D1, h=Hc, rounding2=rt, anchor=BOT);
  // lens recess, flat-bottomed, facing −X
  translate([-(D0/2 - zl*tan(1.5)) + tl, 0, zl]) xcyl(d=dl, h=6, anchor=RIGHT);
}

include <robotics.scad>
// Lens disc seated in the cap recess. Origin: optical centre on the scan axis (x=0,y=0,z=25.70).
D0 = 35.29; zl = 5.0;               // cap Ø at base, lens height above cap base
rs = D0/2 - zl*tan(1.5);            // cap surface radius at lens height ≈ 17.51
dl = 8.1 - 0.2; tl = 1.2;           // disc slightly under recess Ø; recess depth
$fn = 64;
translate([-rs + tl, 0, 0]) xcyl(d=dl, h=tl - 0.05, anchor=RIGHT);

include <robotics.scad>
// Header in the +Y wall pocket. Origin: world origin (modeled in place).
W = 38.59; drft = 2;
cz = 3.8; cw = 9.35; ch = 4.2;                  // scaled from drawing
yf = W/2 - cz*tan(drft);                         // wall face at connector height ≈ 19.16
yb = W/2 + 1 - 7;                                // pocket floor (matches base cut) = 13.30
d  = yf - yb;
$fn = 24;
difference() {
  translate([0, yb, cz]) cuboid([cw, d, ch], rounding=0.3, edges="Y", anchor=FRONT);
  // mating cavity (plain, conservative)
  translate([0, yf + 0.01, cz + 0.2]) cuboid([cw - 1.6, 3.0, ch - 1.6], anchor=BACK);
}
// 4 contacts on 1.5 mm pitch (datasheet pitch)
for (i = [0:3]) translate([(i - 1.5)*1.5, yf - 3.0, cz + 0.2]) cuboid([0.5, 2.6, 0.5], anchor=FRONT);
